(function setupOfficialAbilities() {
  if (typeof FIGURES_DB === "undefined") return;
  FIGURES_DB.forEach((f) => {
    const ab = f.officialDuelId != null ? OFFICIAL_DUEL_ABILITIES[f.officialDuelId] : null;
    if (!ab) return;
    f.officialAbility = ab;
    f.officialAbilityText = ab.n + ": " + ab.t;
    // Figuras sem descrição própria mostram o texto oficial
    if (typeof FIGURE_ABILITIES_DB !== "undefined" && !FIGURE_ABILITIES_DB[f.id]) FIGURE_ABILITIES_DB[f.id] = f.officialAbilityText;
    const fx = ab.fx;
    if (!fx) return;
    f.abilityFx = fx;
    if (fx.pass) f.canPassThrough = true;
    if (fx.mp) f.mp = Math.min(4, (f.mp || 1) + fx.mp);
  });
  // Corrige roletas antigas que não somam 96 (Lapras, Kabutops, Mega Starmie, Mega Lopunny somavam 100):
  // a diferença sai/entra na maior fatia
  FIGURES_DB.forEach((f) => {
    if (!Array.isArray(f.wheel) || !f.wheel.length) return;
    const sum = f.wheel.reduce((a, x) => a + (x.size || 0), 0);
    if (sum === 96) return;
    const big = f.wheel.reduce((m, x) => (x.size > m.size ? x : m), f.wheel[0]);
    if (big.size - (sum - 96) > 0) big.size -= (sum - 96);
  });
  FIGURES_DB.forEach((f) => {
    const sl = f.officialDuelId != null ? OFFICIAL_DUEL_SLICE_FX[f.officialDuelId] : null;
    if (!sl || !Array.isArray(f.wheel)) return;
    Object.keys(sl).forEach((k) => { if (f.wheel[+k]) f.wheel[+k].wfx = sl[k]; });
  });
  if (typeof POKEMON_EVOLUTION_FAMILIES !== "undefined") {
    const seen = new Set(POKEMON_EVOLUTION_FAMILIES.map((x) => x.join(">")));
    OFFICIAL_DUEL_EVO_FAMILIES.forEach((fam) => { if (!seen.has(fam.join(">"))) POKEMON_EVOLUTION_FAMILIES.push(fam); });
    // Tira das famílias os nomes que não existem no FIGURES_DB (ex.: Mega Pidgeot, Weepinbell). Sem isso a peça
    // "evoluía" só no nome e continuava com sprite e roleta da forma anterior.
    const exists = new Set(FIGURES_DB.map((f) => String(f.name).toLowerCase().replace(/[\s\-_]/g, "")));
    for (let i = POKEMON_EVOLUTION_FAMILIES.length - 1; i >= 0; i--) {
      const kept = POKEMON_EVOLUTION_FAMILIES[i].filter((n) => exists.has(String(n).toLowerCase().replace(/[\s\-_]/g, "")));
      if (kept.length >= 2) POKEMON_EVOLUTION_FAMILIES[i] = kept; else POKEMON_EVOLUTION_FAMILIES.splice(i, 1);
    }
  }
})();

function abilityFxOf(unit) {
  if (!unit || typeof FIGURES_DB === "undefined") return null;
  const f = FIGURES_DB[unit.baseIdx];
  return (f && f.abilityFx) || null;
}
function abilityTypesMatch(unit, types) {
  if (!types || !types.length) return true;
  const ut = String(unit.type || (FIGURES_DB[unit.baseIdx] || {}).type || "");
  return types.some((t) => ut.includes(t));
}
function abilityAdjacent(a, b) {
  return a && b && a.location === "board" && b.location === "board" &&
    typeof a.nodeId === "number" && typeof b.nodeId === "number" && (ADJ[a.nodeId] || []).includes(b.nodeId);
}
function abilityTurnOk(when, unit) {
  if (when === "myturn") return state.turn === unit.owner;
  if (when === "oppturn") return state.turn !== unit.owner;
  return true;
}
// Bônus de dano vindo de habilidades (da própria peça e de aliadas/vizinhas no tabuleiro)
function abilityDamageBonus(unit) {
  if (!unit || !state || !Array.isArray(state.units)) return 0;
  let bonus = 0;
  const own = abilityFxOf(unit);
  if (own && own.dmg) own.dmg.forEach((d) => { if (d.scope === "self" && abilityTurnOk(d.when, unit)) bonus += d.amt; });
  if (unit.location !== "board") return bonus;
  state.units.forEach((src) => {
    if (src === unit || src.location !== "board") return;
    const fx = abilityFxOf(src);
    if (!fx || !fx.dmg) return;
    fx.dmg.forEach((d) => {
      if (d.scope === "self") return;
      if (!abilityTurnOk(d.when, src)) return;
      if (d.scope === "adjAll" && abilityAdjacent(src, unit)) bonus += d.amt;
      else if (src.owner === unit.owner && abilityTypesMatch(unit, d.types) &&
        (d.scope === "allies" || (d.scope === "alliesAdj" && abilityAdjacent(src, unit)))) bonus += d.amt;
    });
  });
  return bonus;
}

if (typeof getActiveWheel === "function") {
  const _v701GetActiveWheel = getActiveWheel;
  getActiveWheel = function(unit) {
    const segs = _v701GetActiveWheel(unit);
    const b = abilityDamageBonus(unit);
    if (!b || !Array.isArray(segs)) return segs;
    return segs.map((s) => (s && !s.isZMove && (s.color === "white" || s.color === "gold") && s.dmg > 0) ? Object.assign({}, s, { dmg: s.dmg + b }) : s);
  };
}

if (typeof evaluateCombat === "function") {
  const _v701EvaluateCombat = evaluateCombat;
  evaluateCombat = function(atkUnit, defUnit, atkSpin, defSpin) {
    if (!atkSpin || !defSpin || !atkSpin.chosen || !defSpin.chosen) return _v701EvaluateCombat(atkUnit, defUnit, atkSpin, defSpin);
    let fa = abilityFxOf(atkUnit), fd = abilityFxOf(defUnit);
    if (fa && fa.nullOpp) fd = null;
    if (fd && fd.nullOpp) fa = null;
    const tweak = (spin, oppFx, selfFx) => {
      let c = spin.chosen;
      if (c._abTweaked) return; // evaluateCombat pode rodar 2× com o mesmo giro (Double Chance)
      if (oppFx && oppFx.oppBlueMiss && c.color === "blue") c = Object.assign({}, c, { color: "red", name: "Miss", dmg: 0 });
      if ((c.color === "white" || c.color === "gold") && c.dmg > 0) {
        let dmg = c.dmg;
        if (oppFx && oppFx.halveIn) dmg = Math.floor(dmg / 2);
        if (oppFx && oppFx.lessIn) dmg = Math.max(0, dmg - oppFx.lessIn);
        if (dmg !== c.dmg) c = Object.assign({}, c, { dmg });
      }
      if (c === spin.chosen) c = Object.assign({}, c);
      c._abTweaked = true;
      spin.chosen = c;
    };
    if (fa || fd) { tweak(atkSpin, fd, fa); tweak(defSpin, fa, fd); }
    // Fatias especiais (wfx). Re-giro e efeitos pós-batalha só na batalha real (spin com multiHits);
    // nas simulações de chance (IA / card de inspeção) não consome o sorteio compartilhado.
    const isReal = ("multiHits" in atkSpin) && ("multiHits" in defSpin);
    const notes = [];
    const preSlice = (spin, unit, opp) => {
      let c = spin.chosen;
      const w = c && c.wfx;
      if (!w || c._sliceDone) return;
      if (w.spinAgain && isReal && typeof getActiveWheel === "function") {
        const segs = (getActiveWheel(unit) || []).filter((x) => !(x.wfx && x.wfx.spinAgain));
        const tot = segs.reduce((a, x) => a + (x.size || 0), 0);
        if (tot > 0) {
          const rnd = (typeof nextDeterministicRandom === "function") ? nextDeterministicRandom() : Math.random();
          let r = rnd * tot, pick = segs[segs.length - 1];
          for (const x of segs) { r -= (x.size || 0); if (r < 0) { pick = x; break; } }
          const nc = Object.assign({}, pick);
          if ((nc.color === "white" || nc.color === "gold") && nc.dmg > 0) nc.dmg = w.spinAgain.mult ? nc.dmg * w.spinAgain.mult : nc.dmg + (w.spinAgain.add || 0);
          nc.name = c.name + " ➔ " + pick.name;
          notes.push(`${unit.name}: ${c.name} girou de novo e saiu ${pick.name}`);
          c = nc;
        }
      }
      const cw = c.wfx || {};
      if ((c.color === "white" || c.color === "gold") && c.dmg > 0) {
        let dmg = c.dmg;
        if (cw.vsType && String(opp.type || "").includes(cw.vsType.type)) dmg += cw.vsType.add;
        if (cw.hex && opp.condition && opp.condition !== PokemonCondition.Normal) dmg *= 2;
        if (dmg !== c.dmg) c = Object.assign({}, c, { dmg });
      }
      if (c === spin.chosen) c = Object.assign({}, c);
      c._sliceDone = true;
      spin.chosen = c;
    };
    preSlice(atkSpin, atkUnit, defUnit);
    preSlice(defSpin, defUnit, atkUnit);
    const out = _v701EvaluateCombat(atkUnit, defUnit, atkSpin, defSpin);
    if (notes.length && out) out.reason = (out.reason || "") + " 🔁 " + notes.join(" · ");
    if (isReal) state.__sliceFxPending = [];
    const pend = (fn) => { if (isReal) state.__sliceFxPending.push(fn); };
    [[atkSpin, atkUnit, defUnit, "atk"], [defSpin, defUnit, atkUnit, "def"]].forEach(([spin, unit, opp, side]) => {
      const w = (spin.chosen && spin.chosen.wfx) || {};
      if (w.selfWait) pend(() => { if (unit.location === "board") unit.waitTurns = Math.max(unit.waitTurns || 0, 2); });
      if (w.selfStatus) pend(() => { if (unit.location === "board") unit.condition = PokemonCondition.Panic; });
    });
    if (!out || (out.winner !== "atk" && out.winner !== "def")) return out;
    {
      const winSide = out.winner, loseSide = winSide === "atk" ? "def" : "atk";
      const winU = winSide === "atk" ? atkUnit : defUnit, loseU = winSide === "atk" ? defUnit : atkUnit;
      const winC = (winSide === "atk" ? atkSpin : defSpin).chosen, loseC = (winSide === "atk" ? defSpin : atkSpin).chosen;
      const lw = loseC.wfx || {}, ww = winC.wfx || {};
      const byDamage = (winC.color === "white" || winC.color === "gold") && (loseC.color === "white" || loseC.color === "gold");
      if (lw.reverseAtLeast && byDamage && (winC.dmg || 0) >= lw.reverseAtLeast) {
        out.winner = loseSide; out.effect = "ko";
        out.reason = (out.reason || "") + ` 🔄 ${loseC.name}: o ataque de ${winC.dmg} voltou contra ${winU.name}!`;
        return out;
      }
      if (ww.benchOpp && (out.effect || "ko") === "ko") out.effect = "bench";
      if ((out.effect || "ko") === "ko") {
        const CMAP = { burn: "Burn", panic: "Panic", freeze: "Freeze", paralyze: "Paralyze", poison: "Poison", badpoison: "BadPoison", sleep: "Sleep" };
        if (lw.onLoseStatus && CMAP[lw.onLoseStatus]) pend(() => { if (winU.location === "board") winU.condition = PokemonCondition[CMAP[lw.onLoseStatus]]; });
        if (lw.destinyBond) pend(() => { if (winU.location === "board" && typeof sendToPC === "function") sendToPC(winU); });
      }
    }
    const winSpin = out.winner === "atk" ? atkSpin.chosen : defSpin.chosen;
    const loseFx = out.winner === "atk" ? fd : fa;
    if (!loseFx) return out;
    const eff = out.effect || "ko";
    const statusEff = ["sleep", "spore", "panic", "freeze", "poison", "badpoison", "toxic", "paralyze", "burn"];
    const tag = (txt) => { out.reason = (out.reason || "") + " 🛡️ " + txt; };
    if (loseFx.noKoGold && winSpin.color === "gold" && eff === "ko") { out.winner = "none"; tag("Habilidade: não é nocauteado por Dourado."); return out; }
    if (loseFx.immovable && ["push", "swap", "bench"].includes(eff)) { out.effect = "none"; tag("Habilidade: não pode ser movido."); }
    else if (loseFx.koToBench && eff === "ko") { out.effect = "bench"; tag("Habilidade: vai ao banco em vez de nocaute."); }
    else if (loseFx.immune && statusEff.includes(eff)) {
      const map = { spore: "sleep", toxic: "badpoison" };
      const st = map[eff] || eff;
      if (loseFx.immune.includes("all") || loseFx.immune.includes(st)) { out.effect = "none"; tag("Habilidade: imune a essa condição."); }
    } else if (loseFx.noWait && eff === "wait") { out.effect = "none"; tag("Habilidade: não recebe Espera."); }
    return out;
  };
}

// Efeitos pós-batalha das fatias (status no vencedor, Destiny Bond, Espera em si mesmo…)
function abilityAfterBattle() {
  const list = (state && state.__sliceFxPending) || [];
  state.__sliceFxPending = [];
  list.forEach((fn) => { try { fn(); } catch (e) {} });
}

// Chamado pelo battle.js depois de aplicar o efeito: remove a Espera de quem é imune
function abilityAfterEffect(unit) {
  const fx = abilityFxOf(unit);
  if (fx && fx.noWait && unit.waitTurns > 0) unit.waitTurns = 0;
}
